 static SceneManager Start(){var s=new SceneManager(new GameState(),new LocalScriptLoader());s.LoadScene("world");E(s,"(第一幕 'load! '((\"opened\" #t) (\"tavern\" #t) (\"act\" 2) (\"rehearsal-seen\" #t))) (第二幕剧院 'load! '((\"performance\" #t) (\"performance-day\" 13) (\"audience-result\" \"车辆线索\"))) (set! world-day 14) (set-global! '世界日 world-day) (第二幕生活 'meet-manager!)");C((bool)s.ActiveInterpreter.Eval("(第二幕剧院 'case-followup-ready?)")!,"不用试唱余音即可接续委托");C((int)s.ActiveInterpreter.Eval("(length (第二幕剧院 'arrivals-at \"剧院\"))")! ==0,"试唱余音已移除");E(s,"(第三幕 'start!) (add-item! \"金钱\" 200)");At(s,"剧院");return s;}
