 E(s,"(识别进度 'load! 10) (对方警觉 'load! 0)");Act(s,"辨认车辆特征");C(s.CurrentSceneName=="world"&&Stage(s)=="记录","识别成功返回城市，回调推进到交记录");s=Reload(s);At(s,"剧院");C(Has(s,"交回跟车记录"),"识别记录冷读档保留");Act(s,"交回跟车记录");C(Stage(s)=="核查"&&!Has(s,"询问核查结果"),"交记录后当天等回音");s=Reload(s);At(s,"剧院");C(Stage(s)=="核查"&&!Has(s,"询问核查结果"),"核查时间冷读档不提前");Next(s);C(Has(s,"询问核查结果"),"真实换日后收到核查结果");var findings=Lines(Act(s,"询问核查结果"));C(findings.Contains("车已经卖给")&&findings.Contains("罗科")&&findings.Contains("货运联合公司"),"经理核查车主及办公地点，有车行与货运来源");C(Has(s,"问夜莺旧事")&&!Has(s,"付钱达成协议"),"查实后才问夜莺，尚未开放解决路线");s=Reload(s);C(All(s.CurrentRootNode!).Any(x=>x.Id=="货运公司"&&x.Name=="货运联合公司"),"经理查回地址后，真实地图开放货运联合公司");At(s,"剧院");C(Stage(s)=="旧事"&&Has(s,"问夜莺旧事"),"身份查实冷读档保留");Act(s,"问夜莺旧事");C(Stage(s)=="公司","夜莺说明旧经纪人后进入公司调查");s=Reload(s);At(s,"货运公司");C(Has(s,"调查罗科租处")&&!Has(s,"潜入货运大楼"),"公司调查前不能跳到潜入");var a=s.GameState.Team.FindActor("player")!;int dice=a.ActionDice.Count;var report=Lines(Act(s,"调查罗科租处"));C(a.ActionDice.Count==dice-1&&report.Contains("租用")&&report.Contains("邮寄"),"一枚真实骰查清租用与外寄");C(Stage(s)=="已查清"&&Has(s,"潜入货运大楼"),"调查后开放潜入");s=Reload(s);At(s,"剧院");C(!Has(s,"付钱达成协议")&&!Has(s,"阅读旧合同")&&!Has(s,"护送夜莺")&&!Has(s,"侧门留证"),"剧院移除解决入口与旧准备行动");At(s,"老街酒馆");C(!Has(s,"核对旧演出账"),"酒馆旧账入口清理");At(s,"货运公司");C(Has(s,"付钱达成协议")&&Has(s,"潜入货运大楼"),"公司调查冷读档后两种出口都在货运公司");var infiltration=Reload(s);At(infiltration,"货运公司");Act(infiltration,"潜入货运大楼");C(infiltration.CurrentSceneName=="货运大楼潜入","公司调查接回真实潜入Scenario");int money=s.GameState.Inventory.GetCount("金钱");Act(s,"付钱达成协议");C(s.GameState.Inventory.GetCount("金钱")==money-150,"协议实际扣除150美元");C(!Has(s,"潜入货运大楼")&&!Has(s,"付钱达成协议"),"结案关闭两种出口");At(s,"剧院");C((string)V(s,"case")=="结案"&&Has(s,"提交调查报告"),"结案后回剧院提交报告");
