 var collapse=Start();Enter(collapse);collapse.GameState.Team.FindActor("player")!.Composure=0;collapse.GameState.Team.Injure(Injury.MaxSeverity-1);collapse.EndTurn();C(collapse.CurrentSceneName=="world"&&Stage(collapse)=="守候","真实倒下回执回城市，调查仍可继续");
 var old=Start();E(old,"(第三幕 'load! '((\"version\" 10) (\"started\" #t) (\"start-day\" 14) (\"case\" \"调查\") (\"warehouse\" #t) (\"contract\" #t)))");C(Stage(old)=="已查清","旧档已知档案地点不倒放前置调查");old=Reload(old);At(old,"货运公司");C(Has(old,"潜入货运大楼"),"旧进展实际存档往返后仍可继续");
 Console.WriteLine("第三幕轿车调查检查通过");
 }
}
